    test('handles ]]> in CDATA fields properly', async () => {
        const project = createProject({ config: { scope: SCOPE } })
        project.registerExplicitId('sys_ui_page', 'cdata-test')

        const fluentFile = project.addFile({
            path: 'src/fluent/cdata-test.now.ts',
            content: `import { UiPage } from '@servicenow/sdk/core'
UiPage({
    $id: Now.ID['cdata-test'],
    endpoint: 'x_test_snc_cdata.do',
    html: '<div>HTML with ]]> sequence</div>',
    clientScript: 'console.log("client]]>script");',
    processingScript: 'gs.info("processing]]>script");'
})`,
        })

        const output = await fluentFile.getOutput()
        expect(output).toHaveLength(1)

        // Verify that ]]> is properly escaped in CDATA sections
        expect(output[0].content).toContain('<div>HTML with ]]]]><![CDATA[> sequence</div>')
        expect(output[0].content).toContain(
            '<client_script><![CDATA[console.log("client]]]]><![CDATA[>script");]]></client_script>'
        )
        expect(output[0].content).toContain(
            '<processing_script><![CDATA[gs.info("processing]]]]><![CDATA[>script");]]></processing_script>'
        )
    })
